using System.Collections.Generic;
using UnityEngine;

// Bootstrap and top-level state: start panel -> generating (time-sliced) -> playing. Everything is created
// from code at start-up; the scene file is empty. A new map is only ever generated by pressing Generate (G9).
public class Game : MonoBehaviour
{
    public static Game I;

    public enum State { StartPanel, Generating, Playing }
    public const int MODE_EXPLORE = 0, MODE_HUNT = 1, MODE_HIDE = 2;

    public State state = State.StartPanel;
    public MapBuilder map = new MapBuilder();
    public Player player;
    public Camera cam;
    public Light sun;
    public GameUI ui;
    public Round round;

    // the host's request (start panel)
    public string seedText = "";
    public int size = 0;
    public int density = 0;             // GenData.DensityName index: scales the prop ranges (G24), part of the seed code
    public int mode = MODE_EXPLORE;
    public string panelMessage = "";
    public bool remixOffered;

    // the map being played
    public uint seed;
    public string seedCode = "";
    public bool menuOpen, helpOpen = true, debugOpen, topView;
    public float mouseSensitivity = 1f;
    public bool lowQuality;
    public float fps;
    public float genFrames;
    public string lastCmdResult = "";

    Camera topCam;
    bool wasLocked;
    float menuOpenedAt = -9f;
    float fpsTimer; int fpsFrames;
    int autoMode = -1;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    static void Boot()
    {
        if (I != null) return;
        var go = new GameObject("Game");
        DontDestroyOnLoad(go);
        go.AddComponent<Game>();
    }

    void Awake()
    {
        I = this;
        Layers.Setup();
        GenData.Build();
        ModelLibrary.Load();

        var camGo = new GameObject("Camera");
        cam = camGo.AddComponent<Camera>();
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.56f, 0.76f, 0.93f);
        cam.nearClipPlane = 0.05f; cam.farClipPlane = 220f; cam.fieldOfView = 68f;
        cam.allowMSAA = true; cam.allowHDR = false;
        camGo.AddComponent<AudioListener>();
        camGo.transform.position = new Vector3(0, 12, -14);
        camGo.transform.rotation = Quaternion.Euler(35, 0, 0);

        var sunGo = new GameObject("Sun");
        sun = sunGo.AddComponent<Light>();
        sun.type = LightType.Directional;
        sun.color = new Color(1f, 0.96f, 0.88f);
        sun.intensity = 0.62f;
        sun.shadows = LightShadows.None;
        sunGo.transform.rotation = Quaternion.Euler(52f, 38f, 0f);

        RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Trilight;
        RenderSettings.ambientSkyColor = new Color(0.62f, 0.66f, 0.72f);
        RenderSettings.ambientEquatorColor = new Color(0.52f, 0.53f, 0.54f);
        RenderSettings.ambientGroundColor = new Color(0.50f, 0.48f, 0.45f);
        RenderSettings.fog = true;
        RenderSettings.fogMode = FogMode.Linear;
        RenderSettings.fogColor = cam.backgroundColor;
        RenderSettings.fogStartDistance = 45f; RenderSettings.fogEndDistance = 160f;

        gameObject.AddComponent<AudioHub>();
        ui = gameObject.AddComponent<GameUI>();
        round = gameObject.AddComponent<Round>();
        gameObject.AddComponent<PipScreen>();
        var pgo = new GameObject("Player");
        player = pgo.AddComponent<Player>();

        NewRandomSeed();
        ReadUrl();
    }

    // ---------------------------------------------------------------- seeds
    public void NewRandomSeed()
    {
        // the only use of a non-deterministic source: picking a fresh seed
        uint s = (uint)System.DateTime.UtcNow.Ticks ^ ((uint)Random.Range(0, int.MaxValue) * 2654435761u);
        seedText = SeedCode.Encode(GenData.GEN_VERSION, size, GenRng.Mix(s), density);
        panelMessage = ""; remixOffered = false;
    }

    // the size and density buttons re-write the code in the field, because both are part of it (04 section 6.1)
    public void SetSize(int newSize)
    {
        size = newSize;
        Recode();
    }

    public void SetDensity(int newDensity)
    {
        density = Mathf.Clamp(newDensity, 0, GenData.DensityPercent.Length - 1);
        Recode();
    }

    void Recode()
    {
        int v, sz; uint sd;
        int st = SeedCode.Decode(seedText, GenData.GEN_VERSION, out v, out sz, out sd);
        if (st == SeedCode.OK) seedText = SeedCode.Encode(GenData.GEN_VERSION, size, sd, density);
    }

    static int DensityFromFlags(int flags)
    {
        int d = flags & SeedCode.DENSITY_MASK;
        return d < GenData.DensityPercent.Length ? d : 0;
    }

    // Reads the seed field. Returns true if a map can be generated from it.
    public bool ParseSeed(bool acceptOlder)
    {
        string t = seedText.Trim();
        uint plain;
        if (t.Length > 0 && t.Length <= 10 && uint.TryParse(t, out plain))
        {
            // a plain number takes the size and the density chosen on the panel
            seed = plain; seedCode = SeedCode.Encode(GenData.GEN_VERSION, size, seed, density);
            return true;
        }
        int v, sz, fl; uint sd;
        int st = SeedCode.Decode(t, GenData.GEN_VERSION, out v, out sz, out sd, out fl);
        remixOffered = false;
        if (st == SeedCode.TYPO) { panelMessage = "Typo in the code. A code looks like v" + GenData.GEN_VERSION + "-XXXX-XXXX-XXXX (or type a plain number)."; return false; }
        if (st == SeedCode.NEWER) { panelMessage = "This code needs a newer generator (v" + v + "). This build runs v" + GenData.GEN_VERSION + "."; return false; }
        if (st == SeedCode.OLDER && !acceptOlder)
        {
            panelMessage = "This code was made with generator v" + v + ". This build runs v" + GenData.GEN_VERSION + ", so the map will differ.";
            remixOffered = true;
            return false;
        }
        seed = sd; size = sz; density = DensityFromFlags(fl);
        seedCode = SeedCode.Encode(GenData.GEN_VERSION, size, seed, density);
        return true;
    }

    public void Generate(bool acceptOlder)
    {
        if (!ParseSeed(acceptOlder)) { AudioHub.I.Play("error_004", 0.6f); return; }
        seedText = seedCode;
        panelMessage = "";
        round.Stop();
        player.Deactivate();
        map.Begin(seed, size, density);
        state = State.Generating;
        genFrames = 0;
        menuOpen = false;
        AudioHub.I.Play("confirmation_001", 0.6f);
    }

    public void BackToStart()
    {
        round.Stop();
        player.Deactivate();
        map.Clear();
        state = State.StartPanel;
        menuOpen = false; topView = false;
        if (topCam != null) topCam.enabled = false;
        cam.enabled = true;
        cam.transform.position = new Vector3(0, 12, -14);
        cam.transform.rotation = Quaternion.Euler(35, 0, 0);
        Cursor.lockState = CursorLockMode.None; Cursor.visible = true;
    }

    void StartPlaying()
    {
        state = State.Playing;
        Debug.Log("[prophunt] map ready: " + StatsLine());
        round.Begin(mode);
    }

    public string StatsLine()
    {
        var g = map.gen;
        return "seed " + seedCode + " size " + GenData.SizeName[g.size] + " density " + GenData.DensityName[g.density] + " hash " + g.mapHash.ToString("X8") + " cells " + g.statGroundCells
            + " rooms " + g.nRooms + " props " + g.statProps + " floor " + g.statFloor + " onFurniture " + g.statTop + " groups " + g.statGroups
            + " scenery " + g.statScenery + " slotItems " + g.statSlotItems
            + " leaks " + g.statLeakPlausible + "+" + g.statLeakComedic + " disguiseTypes " + g.menuCount + " loose " + g.statLoose + " sockets " + g.nSockets
            + " rerolls " + g.attempt + " repairs " + g.statRepairs + " genMs " + map.genMs.ToString("0") + " buildMs " + map.buildMs.ToString("0") + " wallMs " + map.wallMs.ToString("0")
            + " frames " + genFrames + " renderers " + map.rendererCount + " colliders " + map.colliderCount;
    }

    void Update()
    {
        fpsFrames++; fpsTimer += Time.unscaledDeltaTime;
        if (fpsTimer >= 0.5f) { fps = fpsFrames / fpsTimer; fpsFrames = 0; fpsTimer = 0f; }

        if (state == State.Generating)
        {
            genFrames++;
            // generation and building share each frame with rendering: about 8 ms of work, then the frame is drawn
            if (map.Step(8f))
            {
                if (map.failed) { panelMessage = map.phase; state = State.StartPanel; map.Clear(); }
                else StartPlaying();
            }
            return;
        }
        if (state == State.Playing)
        {
            // Esc: the browser releases the mouse itself and may keep the key press; losing the mouse opens the menu
            bool locked = Cursor.lockState == CursorLockMode.Locked;
            bool lostMouse = wasLocked && !locked && !menuOpen && !round.InputBlocked;
            wasLocked = locked;
            if (lostMouse) { menuOpen = true; menuOpenedAt = Time.unscaledTime; AudioHub.I.Play("open_001", 0.5f); }
            // the Esc press that released the mouse may arrive a frame later: it must not close the menu again
            else if (Input.GetKeyDown(KeyCode.M) || (Input.GetKeyDown(KeyCode.Escape) && Time.unscaledTime - menuOpenedAt > 0.4f)) ToggleMenu();
            if (Input.GetKeyDown(KeyCode.H)) helpOpen = !helpOpen;
            if (Input.GetKeyDown(KeyCode.F3) || Input.GetKeyDown(KeyCode.Alpha0)) debugOpen = !debugOpen;
        }
    }

    public void ToggleMenu()
    {
        menuOpen = !menuOpen;
        AudioHub.I.Play(menuOpen ? "open_001" : "close_001", 0.5f);
        if (menuOpen) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; wasLocked = false; }
        else if (!round.InputBlocked && !topView) { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; }
    }

    // ---------------------------------------------------------------- top view (debug, for checking builds)
    public void SetTopView(bool on)
    {
        topView = on;
        if (topCam == null)
        {
            var go = new GameObject("TopCamera");
            topCam = go.AddComponent<Camera>();
            topCam.orthographic = true;
            topCam.clearFlags = CameraClearFlags.SolidColor;
            topCam.backgroundColor = new Color(0.12f, 0.14f, 0.16f);
            topCam.nearClipPlane = 1f; topCam.farClipPlane = 200f;
        }
        topCam.enabled = on;
        cam.enabled = !on;
        map.ShowRoofs(!on);
        if (on && map.built) FrameTop(map.gen.W * 2f, map.gen.H * 2f, map.gen.H * 2f + 3f);
    }

    public void FrameTop(float x, float z, float halfHeight)
    {
        topCam.transform.position = new Vector3(x, 80f, z);
        topCam.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
        topCam.orthographicSize = halfHeight;
    }

    // ---------------------------------------------------------------- URL options and the test hook
    void ReadUrl()
    {
        string url = Application.absoluteURL;
        if (string.IsNullOrEmpty(url)) return;
        int q = url.IndexOf('?');
        if (q < 0) return;
        string query = url.Substring(q + 1);
        int hash = query.IndexOf('#');
        if (hash >= 0) query = query.Substring(0, hash);
        var opts = new Dictionary<string, string>();
        foreach (string part in query.Split('&'))
        {
            int eq = part.IndexOf('=');
            if (eq <= 0) continue;
            opts[part.Substring(0, eq).ToLowerInvariant()] = WWWUnescape(part.Substring(eq + 1));
        }
        string v;
        if (opts.TryGetValue("size", out v))
        {
            string s = v.ToUpperInvariant();
            for (int i = 0; i < 4; i++) if (GenData.SizeName[i] == s) SetSize(i);
        }
        if (opts.TryGetValue("density", out v)) SetDensityByName(v);
        if (opts.TryGetValue("mode", out v))
        {
            string m = v.ToLowerInvariant();
            mode = m == "hunt" ? MODE_HUNT : (m == "hide" ? MODE_HIDE : MODE_EXPLORE);
        }
        if (opts.TryGetValue("debug", out v) && v == "1") debugOpen = true;
        if (opts.TryGetValue("help", out v) && v == "0") helpOpen = false;
        if (opts.TryGetValue("lowq", out v) && v == "1") { lowQuality = true; QualitySettings.antiAliasing = 0; cam.allowMSAA = false; }
        if (opts.TryGetValue("seed", out v) && v.Length > 0)
        {
            // ?seed=...&size=... skips the start panel
            seedText = v;
            Generate(true);
        }
    }

    static string WWWUnescape(string s)
    {
        return System.Uri.UnescapeDataString(s.Replace('+', ' '));
    }

    // Called from the page with SendMessage("Game", "Cmd", "..."): used by the build checks, not by players.
    public void Cmd(string line)
    {
        string[] a = line.Trim().Split(' ');
        string r = "ok";
        try
        {
            switch (a[0])
            {
                case "status":
                    r = "state " + state + " mode " + mode + " " + (map.built ? StatsLine() : map.phase) + " | " + player.StatusLine() + " | " + round.StatusLine() + " fps " + fps.ToString("0.0");
                    break;
                case "generate": seedText = a[1]; if (a.Length > 2) SetSizeByName(a[2]); if (a.Length > 3) mode = int.Parse(a[3]); if (a.Length > 4) SetDensityByName(a[4]); Generate(true); break;
                case "rooms": r = RoomStats(); break;
                case "top": SetTopView(a.Length < 2 || a[1] != "0"); break;
                case "frame": SetTopView(true); FrameTop(float.Parse(a[1]), float.Parse(a[2]), float.Parse(a[3])); break;
                case "tp": player.Teleport(new Vector3(float.Parse(a[1]), a.Length > 3 ? float.Parse(a[3]) : 0.05f, float.Parse(a[2]))); break;
                case "look": player.SetLook(float.Parse(a[1]), float.Parse(a[2])); break;
                case "third": player.SetThird(a.Length < 2 || a[1] != "0"); break;
                case "pip": r = PipScreen.I.Command(a); break;
                case "disguise": r = player.TakeDisguiseByName(a[1]); break;
                case "undisguise": player.ToWalker(); break;
                case "key": player.TestKey(a[1]); break;
                case "walk": player.TestWalk(float.Parse(a[1]), float.Parse(a[2]), a.Length > 3 && a[3] == "1"); break;
                case "menu": menuOpen = a.Length < 2 || a[1] != "0"; break;
                case "help": helpOpen = a.Length < 2 || a[1] != "0"; break;
                case "debug": debugOpen = a.Length < 2 || a[1] != "0"; break;
                case "start": BackToStart(); break;
                case "find": r = player.FindProp(a[1]); break;
                case "round": r = round.RoundCommand(a); break;
                case "hud": ui.hidden = a.Length > 1 && a[1] == "0"; break;
                case "timescale": Time.timeScale = float.Parse(a[1]); break;
                default: r = "unknown command"; break;
            }
        }
        catch (System.Exception e) { r = "error " + e.Message; }
        lastCmdResult = r;
        Debug.Log("[prophunt] cmd " + line + " -> " + r);
    }

    void SetSizeByName(string s)
    {
        for (int i = 0; i < 4; i++) if (GenData.SizeName[i] == s.ToUpperInvariant()) size = i;
    }

    // "sparse", "very dense", "verydense", an index 0 to 4 in panel order, or a percentage such as 70
    void SetDensityByName(string s)
    {
        string t = s.ToLowerInvariant().Replace(" ", "").Replace("-", "").Replace("_", "");
        for (int i = 0; i < GenData.DensityName.Length; i++)
        {
            if (GenData.DensityName[i].ToLowerInvariant().Replace(" ", "") == t || GenData.DensityPercent[i].ToString() == t) { SetDensity(i); return; }
        }
        int n;
        if (int.TryParse(t, out n) && n >= 0 && n < GenData.DensityOrder.Length) SetDensity(GenData.DensityOrder[n]);
    }

    // per room type: rooms, floor area, props on the floor and on furniture (for the build checks)
    public string RoomStats()
    {
        var g = map.gen;
        var sb = new System.Text.StringBuilder();
        for (int t = 0; t < 64; t++)
        {
            if (g.statTypeRooms[t] == 0 || t == GenData.R_RELEASE) continue;
            sb.Append(GenData.RoomName(t) + ": " + g.statTypeRooms[t] + " rooms " + g.statTypeCells[t] / 4 + " m2 floor " + g.statTypeFloor[t] + " furniture " + g.statTypeTop[t] + " | ");
        }
        return sb.ToString();
    }
}
